// Fecha del cierre en la zona horaria de la tienda (Europe/Madrid).
const hoy = new Intl.DateTimeFormat('en-CA', {
  timeZone: 'Europe/Madrid', year: 'numeric', month: '2-digit', day: '2-digit',
}).format(new Date());

// 'desde' y 'hasta' son los que usa la peticion de las ventas: sin ellos, la API
// rechazaba la consulta y el cierre salia con 0 ventas.
return [{ json: { hoy, desde: hoy, hasta: hoy } }];

// Calcula el cierre del dia (HU-04).
//
// 'Ventas del dia' = ventas directas + abonos cobrados ese dia (los abonos
// iniciales tambien cuentan: nacen como abono el dia que se crea el apartado).
// Los importes vienen de la API: aqui solo se SUMAN y se redondea al final.
const fecha = $('Fecha de hoy').first().json.hoy;

const ventas = $('Ventas del dia').all().flatMap((i) => (Array.isArray(i.json) ? i.json : [i.json])).filter((v) => v && v.id !== undefined);
const abonos = $('Abonos del dia').all().flatMap((i) => (Array.isArray(i.json) ? i.json : [i.json])).filter((a) => a && a.id !== undefined);

// Las peticiones llevan 'neverError': si la API devuelve un error (una fecha mal formada,
// la tienda caida...) el cierre no puede salir con ceros como si no hubiera habido ventas.
// Se para el flujo y el Error Workflow avisa a la tienda.
for (const nodo of ['Ventas del dia', 'Abonos del dia']) {
  const error = $(nodo).all().map((i) => i.json).find((x) => x && !Array.isArray(x) && x.detail !== undefined);
  if (error) throw new Error(nodo + ': la API no ha devuelto los datos (' + JSON.stringify(error.detail).slice(0, 200) + ')');
}

const FORMAS = ['efectivo', 'tarjeta', 'bizum'];
const porForma = { ventas: {}, abonos: {} };
for (const forma of FORMAS) { porForma.ventas[forma] = 0; porForma.abonos[forma] = 0; }

let ventasTotal = 0;
for (const v of ventas) {
  const forma = FORMAS.includes(v.forma_pago) ? v.forma_pago : 'efectivo';
  const importe = Number(v.importe ?? 0);
  porForma.ventas[forma] += importe;
  ventasTotal += importe;
}

let abonosTotal = 0;
for (const a of abonos) {
  const forma = FORMAS.includes(a.forma_pago) ? a.forma_pago : 'efectivo';
  const importe = Number(a.importe ?? 0);
  porForma.abonos[forma] += importe;
  abonosTotal += importe;
}

const redondear = (n) => Math.round((Number(n) + Number.EPSILON) * 100) / 100;
for (const forma of FORMAS) {
  porForma.ventas[forma] = redondear(porForma.ventas[forma]);
  porForma.abonos[forma] = redondear(porForma.abonos[forma]);
}
ventasTotal = redondear(ventasTotal);
abonosTotal = redondear(abonosTotal);

const cierre = {
  fecha,
  ventas_directas: ventasTotal,
  abonos: abonosTotal,
  total: redondear(ventasTotal + abonosTotal),
  por_forma_pago: porForma,
  num_ventas: ventas.length,
  num_abonos: abonos.length,
  movimientos: ventas.length + abonos.length,
};

// El historico de cierres se guarda en los datos estaticos del flujo (la memoria de
// n8n entre ejecuciones): una entrada por dia, siempre la del ultimo cierre.
const staticData = $getWorkflowStaticData('global');
staticData.cierres = Array.isArray(staticData.cierres) ? staticData.cierres : [];
staticData.cierres = staticData.cierres.filter((c) => c.fecha !== cierre.fecha);
staticData.cierres.push(cierre);
staticData.cierres = staticData.cierres.slice(-120);

return [{ json: { cierre, cierresGuardados: staticData.cierres.length } }];

// Resumen del dia para Marisa (HU-04).
// La API da las fechas como AAAA-MM-DD; en los mensajes van como dia/mes/año.
const fechaES = (f) => {
  const t = String(f ?? '').split('-');
  return t.length === 3 ? t[2].slice(0, 2) + '/' + t[1] + '/' + t[0] : String(f ?? '');
};
const cierre = $input.first().json.cierre;
// 'tienda' quiere decir 'la direccion de la tienda', que resuelve el
// subflujo de notificacion con el fichero de configuracion.
const emailTienda = 'tienda';
const euros = (n) => Number(n ?? 0).toFixed(2).replace('.', ',') + ' EUR';
const escapar = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const filas = [];
for (const forma of ['efectivo', 'tarjeta', 'bizum']) {
  filas.push([
    forma,
    euros(cierre.por_forma_pago.ventas[forma]),
    euros(cierre.por_forma_pago.abonos[forma]),
    euros(cierre.por_forma_pago.ventas[forma] + cierre.por_forma_pago.abonos[forma]),
  ]);
}

const cuerpo = [
  'Cierre de caja del ' + fechaES(cierre.fecha) + ':',
  '',
  'Ventas directas: ' + euros(cierre.ventas_directas) + ' (' + cierre.num_ventas + ' ventas)',
  'Abonos cobrados: ' + euros(cierre.abonos) + ' (' + cierre.num_abonos + ' abonos)',
  'Total del dia: ' + euros(cierre.total),
  '',
  'Desglose por forma de pago:',
  '  Efectivo: ' + euros(cierre.por_forma_pago.ventas.efectivo) + ' en ventas + ' + euros(cierre.por_forma_pago.abonos.efectivo) + ' en abonos',
  '  Tarjeta: ' + euros(cierre.por_forma_pago.ventas.tarjeta) + ' en ventas + ' + euros(cierre.por_forma_pago.abonos.tarjeta) + ' en abonos',
  '  Bizum: ' + euros(cierre.por_forma_pago.ventas.bizum) + ' en ventas + ' + euros(cierre.por_forma_pago.abonos.bizum) + ' en abonos',
].join('\n');

const tabla = '<table border="1" cellpadding="6" cellspacing="0"><tr><th>Forma</th><th>Ventas</th><th>Abonos</th><th>Total</th></tr>'
  + filas.map((f) => '<tr><td>' + f[0] + '</td><td>' + f[1] + '</td><td>' + f[2] + '</td><td>' + f[3] + '</td></tr>').join('')
  + '</table>';

return [{
  json: {
    canal: 'email',
    email: emailTienda,
    asunto: 'Cierre de caja · ' + fechaES(cierre.fecha),
    cuerpo,
    cuerpo_html: '<p>' + escapar(cuerpo).replace(/\n/g, '<br>') + '</p>' + tabla,
  },
}];

// Dia sin movimientos: el flujo lo dice, no falla.
// La API da las fechas como AAAA-MM-DD; en los mensajes van como dia/mes/año.
const fechaES = (f) => {
  const t = String(f ?? '').split('-');
  return t.length === 3 ? t[2].slice(0, 2) + '/' + t[1] + '/' + t[0] : String(f ?? '');
};
const cierre = $input.first().json.cierre;
// 'tienda' quiere decir 'la direccion de la tienda', que resuelve el
// subflujo de notificacion con el fichero de configuracion.
const emailTienda = 'tienda';
const escapar = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const cuerpo = [
  'Cierre de caja del ' + fechaES(cierre.fecha) + ':',
  '',
  'Hoy no ha habido movimientos: ni ventas ni abonos.',
  'Total del dia: 0,00 EUR',
].join('\n');

return [{
  json: {
    canal: 'email',
    email: emailTienda,
    asunto: 'Cierre de caja · ' + fechaES(cierre.fecha),
    cuerpo,
    cuerpo_html: '<p>' + escapar(cuerpo).replace(/\n/g, '<br>') + '</p>',
  },
}];

// Devuelve UN solo item con los datos de la consulta: el nodo HTTP que va despues
// hace una sola peticion, en vez de una por cada item que le llega.
const origen = $('Fecha de hoy').first().json;
return [{ json: { desde: origen.hoy, hasta: origen.hoy } }];
